var e={configTemplates:{intro:{t:0,b:{t:2,i:[{t:3}],s:`可直接貼上的 Klipper 設定區塊與巨集——啟動程序、耗材處理、輸入整形、熱床網格等。複製一個並貼進你的 printer.cfg（用設定編輯器來貼很方便）。`}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`說明`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`關於設定範本`}},close:{t:0,b:{t:2,i:[{t:3}],s:`關閉`}},howToRead:{t:0,b:{t:2,i:[{t:3}],s:`使用方式`}},steps:[{t:0,b:{t:2,i:[{t:3}],s:`依類別篩選，找到想要的巨集或設定區塊。`}},{t:0,b:{t:2,i:[{t:3}],s:`閱讀說明，以及它需要哪些區塊。`}},{t:0,b:{t:2,i:[{t:3}],s:`複製範本，貼進你的設定，再調整數值。`}}],topics:{what:{title:{t:0,b:{t:2,i:[{t:3}],s:`這些是什麼`}},body:{t:0,b:{t:2,i:[{t:3}],s:`一組精選的常用 Klipper 構件：gcode_macros（PRINT_START、PAUSE/RESUME、耗材載入／退出、M600）以及設定區塊（[input_shaper]、[bed_mesh]、[firmware_retraction]…）。它們是起點——請逐一閱讀，並針對你的機器進行調校。`}}},insert:{title:{t:0,b:{t:2,i:[{t:3}],s:`插入範本`}},body:{t:0,b:{t:2,i:[{t:3}],s:`複製範本，再貼進你的 printer.cfg——設定編輯器的原始檢視是個方便的位置。儲存後，重啟韌體即可套用。請務必先檢視數值；此處的預設值合理，但並未針對你的印表機調校。`}}},sections:{title:{t:0,b:{t:2,i:[{t:3}],s:`需要的區塊`}},body:{t:0,b:{t:2,i:[{t:3}],s:`每個範本都會列出它所定義或依賴的設定區塊。若某區塊已存在於你的設定中，請合併其中的鍵，而不要貼上重複的（重複的區塊會在啟動時被拒絕）。`}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`詞彙表`}},body:{t:0,b:{static:``,t:2,i:[]}}}},glossary:{template:{term:{t:0,b:{t:2,i:[{t:3}],s:`範本`}},def:{t:0,b:{t:2,i:[{t:3}],s:`一段可直接貼上的 Klipper 設定或巨集 G-code，可複製到 printer.cfg 中。`}}},macro:{term:{t:0,b:{t:2,i:[{t:3}],s:`gcode_macro`}},def:{t:0,b:{t:2,i:[{t:3}],s:`你在設定中定義的具名指令（例如 PRINT_START），執行一連串的 G-code。`}}},section:{term:{t:0,b:{t:2,i:[{t:3}],s:`區塊`}},def:{t:0,b:{t:2,i:[{t:3}],s:`以 [方括號] 標示的設定區塊，例如 [bed_mesh]——Klipper 設定分組的單位。`}}}}},category:{label:{t:0,b:{t:2,i:[{t:3}],s:`類別`}},all:{t:0,b:{t:2,i:[{t:3}],s:`所有類別`}}},template:{copy:{t:0,b:{t:2,i:[{t:3}],s:`複製`}},copied:{t:0,b:{t:2,i:[{t:3}],s:`已複製！`}},requires:{t:0,b:{t:2,i:[{t:3,v:`區塊：`},{t:4,k:`sections`}]}},requiresNone:{t:0,b:{t:2,i:[{t:3}],s:`-`}}},count:{t:0,b:{t:2,i:[{t:4,k:`n`},{t:3,v:` 個範本`}]}},states:{loading:{t:0,b:{t:2,i:[{t:3}],s:`正在載入範本…`}},error:{t:0,b:{t:2,i:[{t:3}],s:`無法載入範本。`}},empty:{t:0,b:{t:2,i:[{t:3}],s:`此類別中沒有範本。`}},retry:{t:0,b:{t:2,i:[{t:3}],s:`重試`}}},categories:{config_blocks:{t:0,b:{t:2,i:[{t:3}],s:`設定區塊`}},macros:{t:0,b:{t:2,i:[{t:3}],s:`巨集`}}}}};export{e as default};